import { ScrollView } from "react-native";
type Item = { id: string };
const items: Item[] = [];
const Row = (_: { item: Item }) => null;
const List = () => (
  <ScrollView>
    {items.map(i => (
      <Row key={i.id} item={i} />
    ))}
  </ScrollView>
);

import { FlatList } from "react-native";
type Item = { id: string };
const data: Item[] = [];
const Row = (_: { item: Item }) => null;
const List = () => (
  <FlatList data={data} renderItem={Row}
    keyExtractor={i => i.id}
    initialNumToRender={10} />
);
